#include <stdio.h>

/* 8 位补码加法，同时给出三种溢出判据 */
static void try_add(int x, int y) {
    unsigned ux = (unsigned)(unsigned char)(x & 0xFF);
    unsigned uy = (unsigned)(unsigned char)(y & 0xFF);
    unsigned raw = ux + uy;
    unsigned char res = (unsigned char)raw;
    int sx = (int)(ux >> 7), sy = (int)(uy >> 7), sr = (int)(res >> 7);

    unsigned c_out = (raw >> 8) & 1u;                                  /* C7 */
    unsigned c_into = (((ux & 0x7Fu) + (uy & 0x7Fu)) >> 7) & 1u;       /* C6 */
    int ovf_xor = (int)(c_out ^ c_into);

    int ovf_sign = (sx == sy) && (sr != sx);

    int dx = (int)(signed char)(unsigned char)x;
    int dy = (int)(signed char)(unsigned char)y;
    unsigned d9 = (unsigned)((dx + dy) & 0x1FFu);                      /* 9 位双符号位 */
    unsigned db_hi = (d9 >> 8) & 1u;                                   /* 第 1 个符号位 */
    unsigned db_lo = (d9 >> 7) & 1u;                                   /* 第 2 个符号位 */

    int r8 = (int)(signed char)res;
    printf("  %5d + %5d = %6d | %02X + %02X -> %02X | C7^C6=%d  sign=%d  dbl=%u%u  %s\n",
           x, y, r8, ux, uy, (unsigned)res, ovf_xor, ovf_sign, db_hi, db_lo,
           (db_hi == 0u && db_lo == 1u) ? "POS-OVERFLOW"
           : (db_hi == 1u && db_lo == 0u) ? "NEG-OVERFLOW" : "ok");
}

int main(void) {
    printf("=== 8-bit twos-complement addition and overflow ===\n");
    printf("      x  +      y =  8-bit | operands -> result | judge1 judge2 judge3\n");
    try_add(100, 20);
    try_add(105, 65);
    try_add(-100, -20);
    try_add(-105, -65);
    try_add(100, -40);
    try_add(-1, 1);

    printf("\nnotes:\n");
    printf("  judge1 = C7 ^ C6, judge2 = same-sign in / opposite-sign out, judge3 = double sign bits\n");
    printf("  two operands of OPPOSITE sign can never overflow\n");
    printf("  double sign bits shown as two BITS: 00 ok-positive, 11 ok-negative,\n");
    printf("    01 = POS-overflow, 10 = NEG-overflow\n");
    printf("  unsigned addition always wraps mod 256; that is not an error, it is the defined result\n");
    return 0;
}
